<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { http, messageOf } from '../api/http'
import { points } from '../api/writing'
import { getModels, model, price, units, type AdminModel } from './api'
import type { PricePolicy, ProviderTokenPolicy } from '@lanjian/hosted-contracts'
import ProviderPrice from './ProviderPrice.vue'
import { integer, modelId, record } from '@lanjian/hosted-contracts'
const selectedModel = ref(''), selectionRevision = ref(0)
function readSelection(value: unknown) { const p = record(value); selectionRevision.value = integer(p.revision); selectedModel.value = p.modelId === null ? '' : modelId(p.modelId) }
async function saveSelection() { await run(async () => { readSelection(await http.request('/api/admin/active-model', 'PUT', { modelId: selectedModel.value || null, expectedRevision: selectionRevision.value })); notice.value = '在线创作模型已更新。新任务使用此模型，已受理任务沿用原配置。' }) }
const models = ref<AdminModel[]>([]), busy = ref(false), error = ref(''), notice = ref(''), key = ref('')
const blank = () => ({ id: '', name: '', protocol: 'openai-compatible' as AdminModel['protocol'], baseUrl: '', model: '', enabled: false, maxInputTokens: 64000, maxOutputTokens: 4096, revision: 0, keyConfigured: false })
const form = reactive(blank()), mode = ref<PricePolicy['mode']>('unconfigured'), rate = ref('1'), inputRate = ref('1'), outputRate = ref('3'), version = ref(0)
const defaultProviderPolicy = (): ProviderTokenPolicy => ({ mode: 'provider-tokens', currency: 'USD', usdToCny: '6.64', pointsPerCny: '20', groupName: '默认', groupMultiplier: '1', sourceVersion: '管理员配置', tiers: [{ name: 'standard', through: null, rates: { input: '0', output: '0', cacheRead: '0', cacheWrite: '0', cacheWrite1h: '0' } }] })
const providerPolicy = ref<ProviderTokenPolicy | null>(defaultProviderPolicy())
async function run(work: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await work() } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function choose(m: AdminModel) { await run(async () => { const p = price(await http.request(`/api/admin/pricing/${encodeURIComponent(m.id)}`)); Object.assign(form, m); key.value = ''; mode.value = p.policy.mode; version.value = p.version; providerPolicy.value = p.policy.mode === 'provider-tokens' ? p.policy : defaultProviderPolicy(); if (p.policy.mode === 'request') rate.value = points(p.policy.points); if (p.policy.mode === 'tokens') { inputRate.value = points(p.policy.inputPerMillion); outputRate.value = points(p.policy.outputPerMillion) } }) }
function create() { Object.assign(form, blank()); key.value = ''; version.value = 0; mode.value = 'unconfigured'; providerPolicy.value = defaultProviderPolicy(); notice.value = ''; error.value = '' }
async function saveModel() { await run(async () => {
  const { id, revision, keyConfigured: _configured, ...fields } = form
  const saved = model(await http.request(`/api/admin/models/${encodeURIComponent(id)}`, 'PUT', { ...fields, expectedRevision: revision, ...(key.value ? { apiKey: key.value } : {}) }))
  key.value = ''; Object.assign(form, saved); notice.value = '模型连接已保存。';
  try { models.value = await getModels(); readSelection(await http.request('/api/admin/active-model')) } catch { notice.value += ' 列表刷新失败，请重新打开此页。' }
}) }
async function savePrice() { await run(async () => {
  if (mode.value === 'provider-tokens' && !providerPolicy.value) throw new Error('请先导入已核对的供应商费率。')
  const policy: PricePolicy = mode.value === 'request' ? { mode: 'request', points: units(rate.value) } : mode.value === 'tokens' ? { mode: 'tokens', inputPerMillion: units(inputRate.value), outputPerMillion: units(outputRate.value) } : mode.value === 'provider-tokens' ? providerPolicy.value! : { mode: 'unconfigured' }
  const p = price(await http.request(`/api/admin/pricing/${encodeURIComponent(form.id)}`, 'PUT', { expectedVersion: version.value, policy })); version.value = p.version; notice.value = `计费版本 ${p.version} 已保存，已受理任务继续沿用原费率。`
}) }
onMounted(() => run(async () => { models.value = await getModels(); readSelection(await http.request('/api/admin/active-model')) }))
</script>
<template><section class="admin-section"><header><div><h2>模型连接</h2></div><button :disabled="busy" @click="create">＋ 新建连接</button></header><p>用户统一使用你指定的模型，无需配置接口或选择渠道。</p><form class="paper-card" @submit.prevent="saveSelection"><label>在线创作使用的唯一模型<select v-model="selectedModel" :disabled="busy"><option value="">暂停 AI 创作</option><option v-for="m in models" :key="m.id" :value="m.id" :disabled="!m.enabled || !m.keyConfigured">{{ m.name }} · {{ m.model }}</option></select></label><button class="primary" :disabled="busy">应用到在线创作</button></form><p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status" class="success">{{ notice }}</p><div class="admin-model-list"><button v-for="m in models" :key="m.id" :disabled="busy" :class="{ selected: form.id === m.id }" @click="choose(m)">{{ m.name }} · {{ m.enabled ? '已启用' : '停用' }} · {{ m.keyConfigured ? '密钥已配置' : '缺少密钥' }}</button></div><fieldset :disabled="busy" class="admin-two-columns"><form class="paper-card" @submit.prevent="saveModel"><h3>接口连接</h3><label>连接标识<input v-model="form.id" :disabled="form.revision > 0" required pattern="[a-zA-Z0-9][a-zA-Z0-9._-]*" placeholder="例如 main-model"></label><label>显示名称<input v-model="form.name" required maxlength="80"></label><label>接口协议<select v-model="form.protocol"><option value="openai-compatible">OpenAI 兼容接口</option><option value="gemini-native">Gemini 原生接口</option></select></label><label>服务地址<input v-model="form.baseUrl" type="url" required placeholder="https://服务地址/v1"></label><label>模型名称<input v-model="form.model" required maxlength="150"></label><label>API 密钥 {{ form.keyConfigured ? '（留空保留）' : '' }}<input v-model="key" type="password" autocomplete="new-password" :required="!form.keyConfigured" maxlength="8192"></label><p class="muted">密钥写入后不会回显。更改地址或协议时，请重新填写密钥。</p><div class="form-row"><label>输入预算上限<input v-model.number="form.maxInputTokens" type="number" min="1000" max="200000" required></label><label>输出 token 上限<input v-model.number="form.maxOutputTokens" type="number" min="256" max="32768" required></label></div><p class="muted">输入按请求字节保守预留；tokens 模式按供应商实际用量结算。</p><label class="check-label"><input v-model="form.enabled" type="checkbox">启用此连接（选为在线模型后供用户使用）</label><button class="primary">保存模型连接</button></form><form class="paper-card" @submit.prevent="savePrice"><h3>使用积分</h3><label>计费方式<select v-model="mode"><option value="unconfigured">尚未配置 / 暂停付费任务</option><option value="request">按完成的任务</option><option value="tokens">按实际 tokens</option><option value="provider-tokens">按供应商实际成本（含缓存及阶梯）</option></select></label><template v-if="mode === 'request'"><label>每个任务的积分<input v-model="rate" inputmode="decimal" required></label><p>生成出可保留的候选或部分内容时扣费一次。一个任务内的多次调用不会重复收取任务费用。</p></template><template v-else-if="mode === 'tokens'"><label>每百万输入 tokens 的积分<input v-model="inputRate" inputmode="decimal" required></label><label>每百万输出 tokens 的积分<input v-model="outputRate" inputmode="decimal" required></label><p>每次调用先预留预算，再按服务端收到的实际用量结算。没有可靠用量的调用需人工核对。</p></template><ProviderPrice v-else-if="mode === 'provider-tokens' && providerPolicy" v-model:policy="providerPolicy" /><p v-else>未配置费率时，用户可手动写作，但不能发起此模型的 AI 任务。</p><p class="muted">新账户赠送 10 积分，约 0.5 元是运营预算参考。请依据你的模型成本填写积分费率；积分不承诺现金兑换。</p><button class="primary" :disabled="!form.revision">保存计费策略</button></form></fieldset></section></template>
